package com.stacklab.service;
import com.stacklab.dto.ApiDtos.*;import com.stacklab.entity.*;import com.stacklab.exception.*;import com.stacklab.repository.*;import jakarta.persistence.criteria.Predicate;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Service public class TaskService{
 private final TaskRepository tasks;private final UserRepository users;private final ProjectRepository projects;private final ActivityRepository activities;private final NotificationRepository notifications;private final CurrentUserService current;
 public TaskService(TaskRepository t,UserRepository u,ProjectRepository p,ActivityRepository a,NotificationRepository n,CurrentUserService c){tasks=t;users=u;projects=p;activities=a;notifications=n;current=c;}
 @Transactional public TaskView create(TaskCreate r){AppUser assignee=user(r.assigneeId());Project project=project(r.projectId());Task t=tasks.save(new Task(r.title(),r.description(),assignee,project,r.deadline(),r.priority(),r.status()==null?TaskStatus.TO_DO:r.status()));activities.save(new ActivityLog(t,project,current.get(),"TASK_CREATED",null,null,t.getTitle()));notifications.save(new Notification(assignee,t,"You have been assigned task: "+t.getTitle()));return TaskView.of(t);}
 @Transactional public TaskView update(Long id,TaskInput r){Task t=tasks.findDetailedById(id).orElseThrow(()->new NotFoundException("Task not found"));AppUser actor=current.get();if(actor.getRole()==Role.EMPLOYEE&&!t.getAssignee().getId().equals(actor.getId()))throw new org.springframework.security.access.AccessDeniedException("Employees may only update their assigned tasks");if(r.version()==null||!Objects.equals(t.getVersion(),r.version()))throw new ConflictException("Stale task version. The task was updated by another request; reload it and retry with the latest version.");
  AppUser oldAssignee=t.getAssignee();String oldTitle=t.getTitle();TaskStatus oldStatus=t.getStatus();Instant oldDeadline=t.getDeadline();Priority oldPriority=t.getPriority();Project oldProject=t.getProject();AppUser assignee=r.assigneeId()==null?oldAssignee:user(r.assigneeId());Project project=r.projectId()==null?oldProject:project(r.projectId());TaskStatus status=actor.getRole()==Role.EMPLOYEE?(r.status()==null?oldStatus:r.status()):r.status();
  if(actor.getRole()==Role.EMPLOYEE&&(r.assigneeId()!=null&&!r.assigneeId().equals(actor.getId())||r.projectId()!=null||r.deadline()!=null||r.priority()!=null||r.title()!=null||r.description()!=null))throw new org.springframework.security.access.AccessDeniedException("Employees may only change task progress status");
  t.update(r.title(),r.description(),assignee,project,r.deadline(),r.priority(),status);log(t,"title",oldTitle,t.getTitle());log(t,"status",oldStatus.name(),t.getStatus().name());log(t,"deadline",oldDeadline.toString(),t.getDeadline().toString());log(t,"priority",oldPriority.name(),t.getPriority().name());
  if(!oldAssignee.getId().equals(assignee.getId())){log(t,"assignee",oldAssignee.getEmail(),assignee.getEmail());notifications.save(new Notification(assignee,t,"You have been assigned task: "+t.getTitle()));}
  if(oldProject.getId()!=project.getId())log(t,"project",oldProject.getName(),project.getName());if(oldStatus!=t.getStatus()){if(t.getStatus()==TaskStatus.COMPLETED)log(t,"completedAt",null,t.getCompletedAt().toString());else if(oldStatus==TaskStatus.COMPLETED)log(t,"completedAt",t.getCompletedAt()==null?null:t.getCompletedAt().toString(),null);}return TaskView.of(t);
 }
 @Transactional(readOnly=true) public Page<TaskView> list(TaskStatus status,Priority priority,Long assigneeId,Long projectId,Boolean overdue,String q,Pageable pageable){AppUser actor=current.get();Specification<Task> spec=(root,query,cb)->{List<Predicate>x=new ArrayList<>();if(status!=null)x.add(cb.equal(root.get("status"),status));if(priority!=null)x.add(cb.equal(root.get("priority"),priority));if(assigneeId!=null)x.add(cb.equal(root.get("assignee").get("id"),assigneeId));if(projectId!=null)x.add(cb.equal(root.get("project").get("id"),projectId));if(q!=null&&!q.isBlank())x.add(cb.like(cb.lower(root.get("title")),"%"+q.toLowerCase()+"%"));if(actor.getRole()==Role.EMPLOYEE)x.add(cb.equal(root.get("assignee").get("id"),actor.getId()));if(Boolean.TRUE.equals(overdue))x.add(cb.and(cb.lessThan(root.get("deadline"),Instant.now()),cb.notEqual(root.get("status"),TaskStatus.COMPLETED)));return cb.and(x.toArray(Predicate[]::new));};return tasks.findAll(spec,pageable).map(TaskView::of);}
 @Transactional(readOnly=true) public TaskView get(Long id){Task t=tasks.findDetailedById(id).orElseThrow(()->new NotFoundException("Task not found"));AppUser u=current.get();if(u.getRole()==Role.EMPLOYEE&&!u.getId().equals(t.getAssignee().getId()))throw new org.springframework.security.access.AccessDeniedException("Task is not assigned to you");return TaskView.of(t);}
 @Transactional public void delete(Long id){Task t=tasks.findById(id).orElseThrow(()->new NotFoundException("Task not found"));activities.save(new ActivityLog(t,t.getProject(),current.get(),"TASK_DELETED",null,t.getTitle(),null));tasks.delete(t);}
 @Transactional public int flagOverdue(){List<Task> items=tasks.findNewlyOverdue(Instant.now());for(Task t:items){t.setOverdueFlag(true);activities.save(new ActivityLog(t,t.getProject(),null,"TASK_OVERDUE","overdue",null,"true"));notifications.save(new Notification(t.getAssignee(),t,"Task is overdue: "+t.getTitle()));}return items.size();}
 private void log(Task t,String f,String o,String n){if(!Objects.equals(o,n))activities.save(new ActivityLog(t,t.getProject(),current.get(),"TASK_UPDATED",f,o,n));}
 private AppUser user(Long id){return users.findById(id).filter(AppUser::isActive).orElseThrow(()->new NotFoundException("Active assignee not found"));}private Project project(Long id){Project p=projects.findById(id).orElseThrow(()->new NotFoundException("Project not found"));if(p.isArchived())throw new IllegalArgumentException("Cannot assign a task to an archived project");return p;}
}
